IDS = ["LY-029","LY-030","LY-031","LY-032","LY-033","LY-034","LY-035","LY-036",
       "LY-102","LY-103","LY-104","LY-105","LY-202","LY-203","LY-204","LY-205",
       "LY-206","LY-207","LY-208","LY-210"]
assert set(P) == set(IDS), (set(IDS) ^ set(P))
sizes = {}
for cid in IDS:
    rec = {"case_id": cid, "prediction_text": P[cid]["prediction_text"],
           "basis": P[cid]["basis"], "confidence": P[cid]["confidence"],
           "trigger": P[cid]["trigger"]}
    assert rec["case_id"] and rec["prediction_text"] and rec["basis"]
    assert 0.0 <= rec["confidence"] <= 1.0
    tr = rec["trigger"]
    assert all(isinstance(tr[k], bool) for k in ("changed_main","reserve_used","disputed"))
    assert isinstance(tr["reason"], str)
    path = OUT / f"{cid}.json"
    path.write_text(json.dumps(rec, ensure_ascii=False, indent=1), encoding="utf-8")
    back = json.loads(path.read_text(encoding="utf-8"))
    assert back == rec, cid
    sizes[cid] = path.stat().st_size
    print(cid, sizes[cid])
cm = sum(P[c]["trigger"]["changed_main"] for c in IDS)
ru = sum(P[c]["trigger"]["reserve_used"] for c in IDS)
di = sum(P[c]["trigger"]["disputed"] for c in IDS)
print("TOTAL", len(IDS), "changed_main", cm, "reserve_used", ru, "disputed", di)
print(json.dumps(sizes, ensure_ascii=False))
